('g6_1_math_u6_L01_basic#1','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',1,'mc','auto','겉넓이란 무엇인가요?',ARRAY['M6-1-u6-X01','M6-1-u6-X18']::text[],true,'{"seq":1,"concept":"M6-1-u6-C1","difficulty":1,"kind":"mc","stem":"겉넓이란 무엇인가요?","options":[{"t":"입체도형의 겉면의 넓이","correct":true},{"t":"입체도형이 담을 수 있는 양","mis":"M6-1-u6-X01"},{"t":"가장 긴 모서리의 길이","mis":"M6-1-u6-X18"},{"t":"꼭짓점의 개수","mis":"M6-1-u6-X18"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고, 마주 보는 면은 합동이에요.","겉넓이는 겉면 여섯 면의 넓이, 부피는 공간에서 차지하는 크기예요.","정답은 「입체도형의 겉면의 넓이」예요."],"variant_rule":{"alt":[{"stem":"부피란 무엇인가요?","options":[{"t":"입체도형이 공간에서 차지하는 크기","correct":true},{"t":"입체도형의 겉면의 넓이","mis":"M6-1-u6-X01"},{"t":"모든 모서리의 길이의 합","mis":"M6-1-u6-X18"},{"t":"한 면의 넓이","mis":"M6-1-u6-X01"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고, 마주 보는 면은 합동이에요.","겉넓이는 겉면 여섯 면의 넓이, 부피는 공간에서 차지하는 크기예요.","정답은 「입체도형이 공간에서 차지하는 크기」예요."]},{"stem":"직육면체의 겉면을 이루는 여섯 면은 모두 어떤 도형인가요?","options":[{"t":"직사각형","correct":true},{"t":"삼각형","mis":"M6-1-u6-X18"},{"t":"원","mis":"M6-1-u6-X18"},{"t":"사다리꼴","mis":"M6-1-u6-X18"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고, 마주 보는 면은 합동이에요.","겉넓이는 겉면 여섯 면의 넓이, 부피는 공간에서 차지하는 크기예요.","정답은 「직사각형」이에요."]}]}}'::jsonb),
('g6_1_math_u6_L01_basic#2','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',1,'mc','auto','다음 중 부피를 알아야 하는 상황은 어느 것인가요?',ARRAY['M6-1-u6-X01']::text[],true,'{"seq":2,"concept":"M6-1-u6-C1","difficulty":1,"kind":"mc","stem":"다음 중 부피를 알아야 하는 상황은 어느 것인가요?","options":[{"t":"상자 안에 모래를 얼마나 담을지 알 때","correct":true},{"t":"상자에 포장지를 붙일 때","mis":"M6-1-u6-X01"},{"t":"상자의 겉면을 색칠할 때","mis":"M6-1-u6-X01"},{"t":"상자를 감쌀 종이를 살 때","mis":"M6-1-u6-X01"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「상자 안에 모래를 얼마나 담을지 알 때」예요."],"variant_rule":{"alt":[{"stem":"다음 중 겉넓이를 알아야 하는 상황은 어느 것인가요?","options":[{"t":"청사초롱 겉면에 붙일 한지의 양을 알 때","correct":true},{"t":"청사초롱 안에 담기는 공간의 크기를 알 때","mis":"M6-1-u6-X01"},{"t":"어항에 물을 얼마나 채울지 알 때","mis":"M6-1-u6-X01"},{"t":"상자에 쌓기나무를 몇 개 넣을지 알 때","mis":"M6-1-u6-X01"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「청사초롱 겉면에 붙일 한지의 양을 알 때」예요."]},{"stem":"선물 상자를 포장지로 겹치지 않게 감쌀 때 필요한 종이의 양과 관계있는 것은 어느 것인가요?","options":[{"t":"겉넓이","correct":true},{"t":"부피","mis":"M6-1-u6-X01"},{"t":"모서리의 수","mis":"M6-1-u6-X18"},{"t":"꼭짓점의 수","mis":"M6-1-u6-X18"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「겉넓이」예요."]}]}}'::jsonb),
('g6_1_math_u6_L01_basic#3','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',1,'sa','auto','가로 8 cm, 세로 5 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u6-C1","difficulty":1,"kind":"sa","stem":"가로 8 cm, 세로 5 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["직사각형의 넓이는 가로 × 세로예요.","8 × 5 = 40이에요.","그래서 40 cm²예요."],"mis":"M6-1-u6-X18","variant_rule":{"alt":[{"stem":"가로 7 cm, 세로 6 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["직사각형의 넓이는 가로 × 세로예요.","7 × 6 = 42예요.","그래서 42 cm²예요."]},{"stem":"가로 9 cm, 세로 4 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["직사각형의 넓이는 가로 × 세로예요.","9 × 4 = 36이에요.","그래서 36 cm²예요."]}]}}'::jsonb),
('g6_1_math_u6_L01_basic#4','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',1,'ox','auto','겉넓이는 상자를 감싸는 종이의 양이고, 부피는 상자 안에 담기는 공간의 크기예요.',ARRAY['M6-1-u6-X01']::text[],true,'{"seq":4,"concept":"M6-1-u6-C1","difficulty":1,"kind":"ox","stem":"겉넓이는 상자를 감싸는 종이의 양이고, 부피는 상자 안에 담기는 공간의 크기예요.","answer":"O","reason_options":[{"t":"겉면의 넓이와 공간의 크기는 서로 다른 양이기 때문에","correct":true},{"t":"둘 다 상자의 크기라서 같은 양이기 때문에","mis":"M6-1-u6-X01"}],"mis":"M6-1-u6-X01","explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."],"variant_rule":{"alt":[{"stem":"직육면체의 여섯 면은 모두 직사각형이에요.","answer":"O","reason_options":[{"t":"직육면체는 직사각형 6개로 둘러싸인 도형이기 때문에","correct":true},{"t":"옆면만 직사각형이고 위아래는 다른 모양이기 때문에","mis":"M6-1-u6-X07"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."]},{"stem":"겉넓이는 겉면 여섯 면의 넓이를 모두 더한 것이에요.","answer":"O","reason_options":[{"t":"겉면은 여섯 면으로 이루어져 있기 때문에","correct":true},{"t":"보이는 세 면만 겉면이기 때문에","mis":"M6-1-u6-X03"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."]}]}}'::jsonb),
('g6_1_math_u6_L01_basic#5','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',2,'mc','auto','한 변이 1 m인 정사각형의 넓이는 몇 cm²인가요?',ARRAY['M6-1-u6-X14','M6-1-u6-X13']::text[],true,'{"seq":5,"concept":"M6-1-u6-C1","difficulty":2,"kind":"mc","stem":"한 변이 1 m인 정사각형의 넓이는 몇 cm²인가요?","options":[{"t":"10000 cm²","correct":true},{"t":"100 cm²","mis":"M6-1-u6-X14"},{"t":"1000 cm²","mis":"M6-1-u6-X14"},{"t":"1000000 cm²","mis":"M6-1-u6-X13"}],"explanation":["넓이는 길이를 두 번 곱해 구하므로 단위를 바꿀 때도 두 방향 모두 바꿔요.","1 m = 100 cm이므로 100 × 100 = 10000이에요.","그래서 10000 cm²예요."],"variant_rule":{"alt":[{"stem":"2 m²는 몇 cm²인가요?","options":[{"t":"20000 cm²","correct":true},{"t":"200 cm²","mis":"M6-1-u6-X14"},{"t":"2000 cm²","mis":"M6-1-u6-X14"},{"t":"2000000 cm²","mis":"M6-1-u6-X13"}],"explanation":["넓이는 길이를 두 번 곱해 구하므로 단위를 바꿀 때도 두 방향 모두 바꿔요.","1 m² = 10000 cm²이므로 10000 × 2 = 20000이에요.","그래서 20000 cm²예요."]},{"stem":"3 m²는 몇 cm²인가요?","options":[{"t":"30000 cm²","correct":true},{"t":"300 cm²","mis":"M6-1-u6-X14"},{"t":"3000 cm²","mis":"M6-1-u6-X14"},{"t":"3000000 cm²","mis":"M6-1-u6-X13"}],"explanation":["넓이는 길이를 두 번 곱해 구하므로 단위를 바꿀 때도 두 방향 모두 바꿔요.","1 m² = 10000 cm²이므로 10000 × 3 = 30000이에요.","그래서 30000 cm²예요."]}]}}'::jsonb),
('g6_1_math_u6_L01_basic#6','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',2,'sa','auto','직육면체의 겨냥도에서 색칠한 면(윗면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u6-C1","difficulty":2,"kind":"sa","stem":"직육면체의 겨냥도에서 색칠한 면(윗면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["색칠한 면은 직사각형이에요.","두 변의 길이를 곱하면 4 × 3 = 12예요.","그래서 12 cm²예요."],"mis":"M6-1-u6-X18","asset":{"type":"geo","items":[{"w":168.0,"h":94.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[48.0,97.0],"4 cm"],[[136.0,72.0],"3 cm"],[[158.0,24.0],"2 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체의 겨냥도에서 색칠한 면(앞면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["색칠한 면은 직사각형이에요.","두 변의 길이를 곱하면 5 × 3 = 15예요.","그래서 15 cm²예요."],"asset":{"type":"geo","items":[{"w":180.0,"h":106.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[120.0,24.0,"sw"],"ㅁ":[24.0,72.0,"ne"],"ㅇ":[144.0,72.0,"e"],"ㅂ":[0,96.0,"sw"],"ㅅ":[120.0,96.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"poly":[["ㄴ","ㅂ","ㅅ","ㄷ"]],"lab":[[[60.0,109.0],"5 cm"],[[154.0,90.0],"2 cm"],[[170.0,36.0],"3 cm"]]}],"tag":false}},{"stem":"직육면체의 겨냥도에서 색칠한 면(오른쪽 옆면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["색칠한 면은 직사각형이에요.","두 변의 길이를 곱하면 3 × 5 = 15예요.","그래서 15 cm²예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":166.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,120.0,"ne"],"ㅇ":[132.0,120.0,"e"],"ㅂ":[0,156.0,"sw"],"ㅅ":[96.0,156.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ",