('g6_1_math_u6_L02_challenge#8','math',6,1,'u6','L02','g6_1_math_u6_L02_challenge','lesson_challenge','M6-1-u6-C2',4,'sa','auto','가로 5 cm, 세로 4 cm인 직육면체의 겉넓이가 94 cm²예요. 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u6-C2","difficulty":4,"kind":"sa","stem":"가로 5 cm, 세로 4 cm인 직육면체의 겉넓이가 94 cm²예요. 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["서로 다른 세 면의 합은 94 ÷ 2 = 47이에요.","남은 두 면은 47 − 5 × 4 = 27이고, 이것은 (가로 + 세로) × 높이, 곧 9 × 높이와 같아요.","27 ÷ 9 = 3이므로 높이는 3 cm예요."],"mis":"M6-1-u6-X04","asset":{"type":"geo","items":[{"w":204.0,"h":130.0,"pts":{"ㄱ":[48.0,0,"nw"],"ㄹ":[168.0,0,"ne"],"ㄴ":[0,48.0,"w"],"ㄷ":[120.0,48.0,"sw"],"ㅁ":[48.0,72.0,"ne"],"ㅇ":[168.0,72.0,"e"],"ㅂ":[0,120.0,"sw"],"ㅅ":[120.0,120.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[60.0,133.0],"5 cm"],[[166.0,102.0],"4 cm"],[[194.0,36.0],"?"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 6 cm, 세로 4 cm인 직육면체의 겉넓이가 148 cm²예요. 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["서로 다른 세 면의 합은 148 ÷ 2 = 74예요.","남은 두 면은 74 − 6 × 4 = 50이고, 이것은 (가로 + 세로) × 높이, 곧 10 × 높이와 같아요.","50 ÷ 10 = 5이므로 높이는 5 cm예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":176.3,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,118.8,"ne"],"ㅇ":[190.0,118.8,"e"],"ㅂ":[0,166.3,"sw"],"ㅅ":[142.5,166.3,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[71.2,179.3],"6 cm"],[[188.2,148.6],"4 cm"],[[216.0,59.4],"?"]]}],"tag":false}},{"stem":"가로 8 cm, 세로 5 cm인 직육면체의 겉넓이가 132 cm²예요. 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["서로 다른 세 면의 합은 132 ÷ 2 = 66이에요.","남은 두 면은 66 − 8 × 5 = 26이고, 이것은 (가로 + 세로) × 높이, 곧 13 × 높이와 같아요.","26 ÷ 13 = 2이므로 높이는 2 cm예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":91.4,"pts":{"ㄱ":[45.2,0,"nw"],"ㄹ":[190.0,0,"ne"]