('g6_1_math_u6_L02_challenge#9','math',6,1,'u6','L02','g6_1_math_u6_L02_challenge','lesson_challenge','M6-1-u6-C2',4,'sa','auto','가로 4 cm, 세로 2 cm, 높이 3 cm인 똑같은 상자 두 개를 가로 × 높이인 면끼리 꼭 맞게 붙여 큰 직육면체를 만들었어요. 큰 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u6-C2","difficulty":4,"kind":"sa","stem":"가로 4 cm, 세로 2 cm, 높이 3 cm인 똑같은 상자 두 개를 가로 × 높이인 면끼리 꼭 맞게 붙여 큰 직육면체를 만들었어요. 큰 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["붙이면 세로가 2 × 2 = 4(cm)인 직육면체가 돼요.","세 면의 합은 4 × 4 + 4 × 3 + 4 × 3 = 40이에요.","40 × 2 = 80이므로 80 cm²예요. (두 상자 겉넓이 52 × 2 = 104에서 붙어서 가려진 두 면 4 × 3 × 2 = 24를 빼도 104 − 24 = 80)"],"mis":"M6-1-u6-X18","asset":{"type":"geo","items":[{"w":156.0,"h":106.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[120.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[96.0,24.0,"sw"],"ㅁ":[24.0,72.0,"ne"],"ㅇ":[120.0,72.0,"e"],"ㅂ":[0,96.0,"sw"],"ㅅ":[96.0,96.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,109.0],"4 cm"],[[130.0,90.0],"2 cm"],[[146.0,36.0],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 3 cm, 높이 4 cm인 똑같은 상자 두 개를 가로 × 높이인 면끼리 꼭 맞게 붙여 큰 직육면체를 만들었어요. 큰 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["148"],"explanation":["붙이면 세로가 3 × 2 = 6(cm)인 직육면체가 돼요.","세 면의 합은 5 × 6 + 5 × 4 + 6 × 4 = 74예요.","74 × 2 = 148이므로 148 cm²예요. (두 상자 겉넓이 94 × 2 = 188에서 붙어서 가려진 두 면 5 × 4 × 2 = 40을 빼도 188 − 40 = 148)"],"asset":{"type":"geo","items":[{"w":192.0,"h":142.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[156.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[120.0,36.0,"sw"],"ㅁ":[36.0,96.0,"ne"],"ㅇ":[156.0,96.0,"e"],"ㅂ":[0,132.0,"sw"],"ㅅ":[120.0,132.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[60.0,145.0],"5 cm"],[[160.0,120.0],"3 cm"],[[182.0,48.0],"4 cm"]]}],"tag":false}},{"stem":"가로 6 cm, 세로 2 cm, 높이 5 cm인 똑같은 상자 두 개를 가로 × 높이인 면끼리 꼭 맞게 붙여 큰 직육면체를 만들었어요. 큰 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["148"],"explanation":["붙이면 세로가 2 × 2 = 4(cm)인 직육면체가 돼요.","세 면의 합은 6 × 4 + 6 × 5 + 4 × 5 = 74예요.","74 × 2 = 148이므로 148 cm²예요. (두 상자 겉넓이 104 × 2 = 208에서 붙어서 가려진 두 면 6 × 5 × 2 = 60을 빼도 208 − 60 = 148)"],"asset":{"type":"geo","items":[{"w":204.0,"h":154.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[168.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[144.0,24.0,"sw"],"ㅁ":[24.0,120.0,"ne"],"ㅇ":[168.0,120.0,"e"],"ㅂ":[0,144.0,"sw"],"ㅅ":[144.0,144.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[72.0,157.0],"6 cm"],[[178.0,138.0],"2 cm"],[[194.0,60.0],"5 cm"]]}],"tag":false}}]}}'::jsonb),
('g6_1_math_u6_L02_challenge#10','math',6,1,'u6','L02','g6_1_math_u6_L02_challenge','lesson_challenge','M6-1-u6-C2',4,'essay','teacher','도윤이는 가로 4 cm, 세로 3 cm, 높이 6 cm인 직육면체의 겉넓이를 4 × 3 + 4 × 6 + 3 × 6 = 54(cm²)라고 했어요. 잘못된 점을 찾고 바르게 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u6-C2","difficulty":4,"kind":"essay","stem":"도윤이는 가로 4 cm, 세로 3 cm, 높이 6 cm인 직육면체의 겉넓이를 4 × 3 + 4 × 6 + 3 × 6 = 54(cm²)라고 했어요. 잘못된 점을 찾고 바르게 구해 보세요.","answer_guide":{"answer":"예: 겨냥도에 보이는 세 면만 더했다. 겉넓이는 여섯 면 전부의 넓이이고 마주 보는 면이 합동이므로 세 면의 합을 2배 해야 한다. 54 × 2 = 108이므로 겉넓이는 108 cm²이다.","scoring_points":["세 면만 더한 것이 잘못이라고 찾았는가","마주 보는 면이 합동이라 2배 해야 한다고 썼는가","108 cm²를 구했는가"]},"explanation":["세 면의 합은 54예요.","54 × 2 = 108이에요.","겉넓이는 108 cm²예요."]}'::jsonb),
('g6_1_math_u6_L03_basic#1','math',6,1,'u6','L03','g6_1_math_u6_L03_basic','lesson_basic','M6-1-u6-C3',1,'mc','auto','직육면체의 옆면을 펼친 직사각형의 가로는 무엇과 같나요?',ARRAY['M6-1-u6-X05','M6-1-u6-X18','M6-1-u6-X02']::text[],true,'{"seq":1,"concept":"M6-1-u6-C3","difficulty":1,"kind":"mc","stem":"직육면체의 옆면을 펼친 직사각형의 가로는 무엇과 같나요?","options":[{"t":"한 밑면의 둘레","correct":true},{"t":"한 밑면의 한 변","mis":"M6-1-u6-X05"},{"t":"직육면체의 높이","mis":"M6-1-u6-X18"},{"t":"겉넓이","mis":"M6-1-u6-X02"}],"explanation":["직육면체를 두 밑면과 옆면으로 나눌 수 있어요.","옆면을 펼치면 가로가 한 밑면의 둘레, 세로가 높이인 직사각형이에요.","정답은 「한 밑면의 둘레」예요."],"variant_rule":{"alt":[{"stem":"직육면체의 옆면을 펼친 직사각형의 세로는 무엇과 같나요?","options":[{"t":"직육면체의 높이","correct":true},{"t":"한 밑면의 둘레","mis":"M6-1-u6-X05"},{"t":"한 밑면의 넓이","mis":"M6-1-u6-X02"},{"t":"가장 긴 모서리 4개의 합","mis":"M6-1-u6-X18"}],"explanation":["직육면체를 두 밑면과 옆면으로 나눌 수 있어요.","옆면을 펼치면 가로가 한 밑면의 둘레, 세로가 높이인 직사각형이에요.","정답은 「직육면체의 높이」예요."]},{"stem":"겉넓이를 두 밑면과 옆면으로 나누어 구하는 바른 방법은 어느 것인가요?","options":[{"t":"두 밑면의 넓이 + 한 밑면의 둘레 × 높이","correct":true},{"t":"두 밑면의 넓이 + 한 변 × 높이","mis":"M6-1-u6-X05"},{"t":"한 밑면의 넓이 + 한 밑면의 둘레 × 높이","mis":"M6-1-u6-X03"},{"t":"두 밑면의 넓이 × 높이","mis":"M6-1-u6-X11"}],"explanation":["직육면체를 두 밑면과 옆면으로 나눌 수 있어요.","옆면을 펼치면 가로가 한 밑면의 둘레, 세로가 높이인 직사각형이에요.","정답은 「두 밑면의 넓이 + 한 밑면의 둘레 × 높이」예요."]}]}}'::jsonb),
('g6_1_math_u6_L03_basic#2','math',6,1,'u6','L03','g6_1_math_u6_L03_basic','lesson_basic','M6-1-u6-C3',1,'sa','auto','가로 4 cm, 세로 2 cm인 직육면체에서 두 밑면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u6-C3","difficulty":1,"kind":"sa","stem":"가로 4 cm, 세로 2 cm인 직육면체에서 두 밑면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["두 밑면은 합동인 직사각형이에요.","4 × 2 × 2 = 16이에요.","그래서 16 cm²예요."],"mis":"M6-1-u6-X07","variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 3 cm인 직육면체에서 두 밑면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["두 밑면은 합동인 직사각형이에요.","5 × 3 × 2 = 30이에요.","그래서 30 cm²예요."]},{"stem":"가로 6 cm, 세로 4 cm인 직육면체에서 두 밑면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["두 밑면은 합동인 직사각형이에요.","6 × 4 × 2 = 48이에요.","그래서 48 cm²예요."]}]}}'::jsonb),
('g6_1_math_u6_L03_basic#3','math',6,1,'u6','L03','g6_1_math_u6_L03_basic','lesson_basic','M6-1-u6-C3',1,'mc','auto','정육면체의 겉넓이를 구하는 바른 방법은 어느 것인가요?',ARRAY['M6-1-u6-X06','M6-1-u6-X04']::text[],true,'{"seq":3,"concept":"M6-1-u6-C3","difficulty":1,"kind":"mc","stem":"정육면체의 겉넓이를 구하는 바른 방법은 어느 것인가요?","options":[{"t":"한 면의 넓이 × 6","correct":true},{"t":"한 면의 넓이 × 4","mis":"M6-1-u6-X06"},{"t":"한 모서리 × 6","mis":"M6-1-u6-X06"},{"t":"한 면의 넓이 × 2","mis":"M6-1-u6-X04"}],"explanation":["정육면체는 여섯 면이 모두 합동인 정사각형이에요.","그래서 한 면의 넓이만 구해 6배 하면 겉넓이예요.","정답은 「한 면의 넓이 × 6」이에요."],"variant_rule":{"alt":[{"stem":"정육면체의 겉넓이를 한 면의 넓이의 6배로 구할 수 있는 까닭은 무엇인가요?","options":[{"t":"여섯 면이 모두 합동인 정사각형이라 넓이가 같기 때문에","correct":true},{"t":"보이는 면이 여섯 개이기 때문에","mis":"M6-1-u6-X03"},{"t":"모서리가 여섯 개이기 때문에","mis":"M6-1-u6-X06"},{"t":"옆면이 여섯 개이기 때문에","mis":"M6-1-u6-X05"}],"explanation":["정육면체는 여섯 면이 모두 합동인 정사각형이에요.","그래서 한 면의 넓이만 구해 6배 하면 겉넓이예요.","정답은 「여섯 면이 모두 합동인 정사각형이라 넓이가 같기 때문에」예요."]},{"stem":"정육면체의 겉넓이를 바르게 구한 식은 어느 것인가요? (한 모서리 5 cm)","options":[{"t":"5 × 5 × 6","correct":true},{"t":"5 × 5 × 4","mis":"M6-1-u6-X06"},{"t":"5 × 6","mis":"M6-1-u6-X06"},{"t":"5 × 5 × 2","mis":"M6-1-u6-X04"}],"explanation":["정육면체는 여섯 면이 모두 합동인 정사각형이에요.","그래서 한 면의 넓이만 구해 6배 하면 겉넓이예요.","정답은 「5 × 5 × 6」이에요."]}]}}'::jsonb),
('g6_1_math_u6_L03_basic#4','math',6,1,'u6','L03','g6_1_math_u6_L03_basic','lesson_basic','M6-1-u6-C3',1,'ox','auto','옆면을 펼친 직사각형의 가로는 한 밑면의 한 변과 같아요.',ARRAY['M6-1-u6-X05']::text[],true,'{"seq":4,"concept":"M6-1-u6-C3","difficulty":1,"kind":"ox","stem":"옆면을 펼친 직사각형의 가로는 한 밑면의 한 변과 같아요.","answer":"X","reason_options":[{"t":"옆면 네 개가 이어져 가로가 한 밑면의 둘레가 되기 때문에","correct":true},{"t":"옆면은 한 면만 펼치기 때문에","mis":"M6-1-u6-X05"}],"mis":"M6-1-u6-X05","explanation":["겉넓이 = 두 밑면 + 옆면이고, 옆면의 가로는 한 밑면의 둘레예요.","정육면체는 한 면의 넓이 × 6이에요.","겉넓이가 작을수록 포장지가 덜 들어요."],"variant_rule":{"alt":[{"stem":"겉넓이는 두 밑면의 넓이와 옆면의 넓이를 더해서 구할 수 있어요.","answer":"O","reason_options":[{"t":"두 밑면과 옆면 네 개가 겉면 여섯 면 전부이기 때문에","correct":true},{"t":"옆면은 겉면이 아니기 때문에","mis":"M6-1-u6-X03"}],"explanation":["겉넓이 = 두 밑면 + 옆면이고, 옆면의 가로는 한 밑면의 둘레예요.","정육면체는 한 면의 넓이 × 6이에요.","겉넓이가 작을수록 포장지가 덜 들어요."]},{"stem":"정육면체의 겉넓이는 한 면의 넓이를 4배 해서 구해요.","answer":"X","reason_options":[{"t":"정육면체는 합동인 면이 여섯 개라 6배 해야 하기 때문에","correct":true},{"t":"정사각형은 변이 4개이기 때문에","mis":"M6-1-u6-X06"}],"explanation":["겉넓이 = 두 밑면 + 옆면이고, 옆면의 가로는 한 밑면의 둘레예요.","정육면체는 한 면의 넓이 × 6이에요.","겉넓이가 작을수록 포장지가 덜 들어요."]}]}}'::jsonb),
