('g6_1_math_u6_L03_basic#7','math',6,1,'u6','L03','g6_1_math_u6_L03_basic','lesson_basic','M6-1-u6-C3',2,'sa','auto','가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 나누어 구하면 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u6-C3","difficulty":2,"kind":"sa","stem":"가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 나누어 구하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["52"],"explanation":["두 밑면은 4 × 2 × 2 = 16(cm²)예요.","옆면의 가로는 한 밑면의 둘레 4 + 2 + 4 + 2 = 12, 옆면은 12 × 3 = 36(cm²)예요.","겉넓이는 16 + 36 = 52(cm²)예요."],"mis":"M6-1-u6-X05","asset":{"type":"geo","items":[{"w":282.0,"h":126.0,"pts":{},"show":[],"poly":[[[36,0],[108.0,0],[108.0,36.0],[36,36.0]],[[36,90.0],[108.0,90.0],[108.0,126.0],[36,126.0]],[[36,36.0],[108.0,36.0],[108.0,90.0],[36,90.0]],[[108.0,36.0],[144.0,36.0],[144.0,90.0],[108.0,90.0]],[[144.0,36.0],[216.0,36.0],[216.0,90.0],[144.0,90.0]],[[216.0,36.0],[252.0,36.0],[252.0,90.0],[216.0,90.0]]],"lab":[[[72.0,-10],"4 cm"],[[14,18.0],"2 cm"],[[276.0,63.0],"3 cm"],[[126.0,26.0],"2 cm"],[[180.0,26.0],"4 cm"],[[234.0,26.0],"2 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 나누어 구하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["94"],"explanation":["두 밑면은 5 × 3 × 2 = 30(cm²)예요.","옆면의 가로는 한 밑면의 둘레 5 + 3 + 5 + 3 = 16, 옆면은 16 × 4 = 64(cm²)예요.","겉넓이는 30 + 64 = 94(cm²)예요."],"asset":{"type":"geo","items":[{"w":336.0,"h":168.7,"pts":{},"show":[],"poly":[[[36,0],[120.4,0],[120.4,50.6],[36,50.6]],[[36,118.1],[120.4,118.1],[120.4,168.7],[36,168.7]],[[36,50.6],[120.4,50.6],[120.4,118.1],[36,118.1]],[[120.4,50.6],[171.0,50.6],[171.0,118.1],[120.4,118.1]],[[171.0,50.6],[255.4,50.6],[255.4,118.1],[171.0,118.1]],[[255.4,50.6],[306.0,50.6],[306.0,118.1],[255.4,118.1]]],"lab":[[[78.2,-10],"5 cm"],[[14,25.3],"3 cm"],[[330.0,84.3],"4 cm"],[[145.7,40.6],"3 cm"],[[213.2,40.6],"5 cm"],[[280.7,40.6],"3 cm"]]}],"tag":false}},{"stem":"가로 6 cm, 세로 2 cm, 높이 5 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 나누어 구하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["104"],"explanation":["두 밑면은 6 × 2