('g6_1_math_u6_L03_challenge#3','math',6,1,'u6','L03','g6_1_math_u6_L03_challenge','lesson_challenge','M6-1-u6-C3',3,'sa','auto','가로 10 cm, 세로 7 cm, 높이 4 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 나누어 구하면 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u6-C3","difficulty":3,"kind":"sa","stem":"가로 10 cm, 세로 7 cm, 높이 4 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 나누어 구하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["276"],"explanation":["두 밑면은 10 × 7 × 2 = 140(cm²)예요.","옆면의 가로는 한 밑면의 둘레 10 + 7 + 10 + 7 = 34, 옆면은 34 × 4 = 136(cm²)예요.","겉넓이는 140 + 136 = 276(cm²)예요."],"mis":"M6-1-u6-X05","asset":{"type":"geo","items":[{"w":336.0,"h":143.0,"pts":{},"show":[],"poly":[[[36,0],[115.4,0],[115.4,55.6],[36,55.6]],[[36,87.4],[115.4,87.4],[115.4,143.0],[36,143.0]],[[36,55.6],[115.4,55.6],[115.4,87.4],[36,87.4]],[[115.4,55.6],[171.0,55.6],[171.0,87.4],[115.4,87.4]],[[171.0,55.6],[250.4,55.6],[250.4,87.4],[171.0,87.4]],[[250.4,55.6],[306.0,55.6],[306.0,87.4],[250.4,87.4]]],"lab":[[[75.7,-10],"10 cm"],[[14,27.8],"7 cm"],[[330.0,71.5],"4 cm"],[[143.2,45.6],"7 cm"],[[210.7,45.6],"10 cm"],[[278.2,45.6],"7 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 12 cm, 세로 5 cm, 높이 6 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 나누어 구하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["324"],"explanation":["두 밑면은 12 × 5 × 2 = 120(cm²)예요.","옆면의 가로는 한 밑면의 둘레 12 + 5 + 12 + 5 = 34, 옆면은 34 × 6 = 204(cm²)예요.","겉넓이는 120 + 204 = 324(cm²)예요."],"asset":{"type":"geo","items":[{"w":336.0,"h":127.0,"pts":{},"show":[],"poly":[[[36,0],[131.3,0],[131.3,39.7],[36,39.7]],[[36,87.3],[131.3,87.3],[131.3,127.0],[36,127.0]],[[36,39.7],[131.3,39.7],[131.3,87.3],[36,87.3]],[[131.3,39.7],[171.0,39.7],[171.0,87.3],[131.3,87.3]],[[171.0,39.7],[266.3,39.7],[266.3,87.3],[171.0,87.3]],[[266.3,39.7],[306.0,39.7],[306.0,87.3],[266.3,87.3]]],"lab":[[[83.7,-10],"12 cm"],[[14,19.9],"5 cm"],[[330.0,63.5],"6 cm"],[[151.2,29.7],"5 cm"],[[218.7,29.7],"12 cm"],[[286.1,29.7],"5 cm"]]}],"tag":false}},{"stem":"가로 9 cm, 세로 8 cm, 높이 5 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 나누어 구하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["314"],