('g6_1_math_u6_L05_challenge#9','math',6,1,'u6','L05','g6_1_math_u6_L05_challenge','lesson_challenge','M6-1-u6-C5',4,'sa','auto','가로 12 cm, 세로 8 cm, 높이 6 cm인 직육면체 모양 상자에 한 모서리가 2 cm인 정육면체 블록을 빈틈없이 채우려고 해요. 블록은 모두 몇 개 들어가나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u6-C5","difficulty":4,"kind":"sa","stem":"가로 12 cm, 세로 8 cm, 높이 6 cm인 직육면체 모양 상자에 한 모서리가 2 cm인 정육면체 블록을 빈틈없이 채우려고 해요. 블록은 모두 몇 개 들어가나요? 숫자로 쓰세요.","answer":["72"],"explanation":["가로에 12 ÷ 2 = 6개, 세로에 8 ÷ 2 = 4개, 높이에 6 ÷ 2 = 3개가 놓여요.","6 × 4 × 3 = 72예요.","그래서 72개예요."],"mis":"M6-1-u6-X10","asset":{"type":"geo","items":[{"w":226.0,"h":128.7,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,71.2,"ne"],"ㅇ":[190.0,71.2,"e"],"ㅂ":[0,118.7,"sw"],"ㅅ":[142.5,118.7,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[71.2,131.7],"12 cm"],[[188.2,101.0],"8 cm"],[[216.0,35.6],"6 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 15 cm, 세로 9 cm, 높이 6 cm인 직육면체 모양 상자에 한 모서리가 3 cm인 정육면체 블록을 빈틈없이 채우려고 해요. 블록은 모두 몇 개 들어가나요? 숫자로 쓰세요.","answer":["30"],"explanation":["가로에 15 ÷ 3 = 5개, 세로에 9 ÷ 3 = 3개, 높이에 6 ÷ 3 = 2개가 놓여요.","5 × 3 × 2 = 30이에요.","그래서 30개예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":112.3,"pts":{"ㄱ":[43.8,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,43.8,"w"],"ㄷ":[146.2,43.8,"sw"],"ㅁ":[43.8,58.5,"ne"],"ㅇ":[190.0,58.5,"e"],"ㅂ":[0,102.3,"sw"],"ㅅ":[146.2,102.3,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[73.1,115.3],"15 cm"],[[190.1,86.4],"9 cm"],[[216.0,29.2],"6 cm"]]}],"tag":false}},{"stem":"가로 20 cm, 세로 10 cm, 높이 8 cm인 직육면체 모양 상자에 한 모서리가 2 cm인 정육면체 블록을 빈틈없이 채우려고 해요. 블록은 모두 몇 개 들어가나요? 숫자로 쓰세요.","answer":["200"],"explanation":["가로에 20 ÷ 2 = 10개, 세로에 10 ÷ 2 = 5개, 높이에 8 ÷ 2 = 4개가 놓여요.","10 × 5 × 4 = 200이에요.","그래서 200개예요."],"asset":{"type":"geo"