('g6_1_math_u6_L07_basic#3','math',6,1,'u6','L07','g6_1_math_u6_L07_basic','lesson_basic','M6-1-u6-C7',1,'ox','auto','두부를 자르면 조각들의 부피의 합은 처음과 같아요.',ARRAY['M6-1-u6-X15']::text[],true,'{"seq":3,"concept":"M6-1-u6-C7","difficulty":1,"kind":"ox","stem":"두부를 자르면 조각들의 부피의 합은 처음과 같아요.","answer":"O","reason_options":[{"t":"조각을 도로 붙이면 처음 두부가 되기 때문에","correct":true},{"t":"잘라 낸 만큼 부피가 늘어나기 때문에","mis":"M6-1-u6-X15"}],"mis":"M6-1-u6-X15","explanation":["잘라도 조각을 모두 모으면 처음과 같아 부피는 변하지 않아요.","한 번 자를 때마다 새 면이 2개씩 생겨 겉넓이는 늘어나요.","부피와 겉넓이는 서로 다른 양이에요."],"variant_rule":{"alt":[{"stem":"두부를 자르면 조각들의 겉넓이의 합은 처음과 같아요.","answer":"X","reason_options":[{"t":"자른 자리에 새 겉면이 생겨 겉넓이가 늘어나기 때문에","correct":true},{"t":"부피가 그대로이니 겉넓이도 그대로이기 때문에","mis":"M6-1-u6-X16"}],"explanation":["잘라도 조각을 모두 모으면 처음과 같아 부피는 변하지 않아요.","한 번 자를 때마다 새 면이 2개씩 생겨 겉넓이는 늘어나요.","부피와 겉넓이는 서로 다른 양이에요."]},{"stem":"두부를 똑같이 4조각으로 자르면 한 조각의 부피는 처음 부피를 4로 나눈 것과 같아요.","answer":"O","reason_options":[{"t":"부피의 합은 그대로이고 똑같이 나누었기 때문에","correct":true},{"t":"자를수록 부피의 합이 줄어들기 때문에","mis":"M6-1-u6-X15"}],"explanation":["잘라도 조각을 모두 모으면 처음과 같아 부피는 변하지 않아요.","한 번 자를 때마다 새 면이 2개씩 생겨 겉넓이는 늘어나요.","부피와 겉넓이는 서로 다른 양이에요."]}]}}'::jsonb),
