('g6_1_math_u6_L07_challenge#6','math',6,1,'u6','L07','g6_1_math_u6_L07_challenge','lesson_challenge','M6-1-u6-C7',3,'sa','auto','가로 10 cm, 세로 10 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 4조각으로 잘랐어요. 조각들의 겉넓이의 합은 처음보다 몇 cm² 늘어났나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u6-C7","difficulty":3,"kind":"sa","stem":"가로 10 cm, 세로 10 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 4조각으로 잘랐어요. 조각들의 겉넓이의 합은 처음보다 몇 cm² 늘어났나요? 숫자로 쓰세요.","answer":["300"],"explanation":["3번 자르면 새 면이 3 × 2 = 6개 생겨요.","새 면 하나는 10 × 5 = 50, 50 × 6 = 300이에요.","그래서 300 cm² 늘어났어요."],"mis":"M6-1-u6-X16","asset":{"type":"geo","items":[{"w":226.0,"h":136.6,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,63.3,"ne"],"ㅇ":[190.0,63.3,"e"],"ㅂ":[0,126.6,"sw"],"ㅅ":[126.7,126.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,139.6],"10 cm"],[[180.3,100.9],"10 cm"],[[216.0,31.6],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 12 cm, 세로 10 cm, 높이 4 cm인 두부를 가로가 똑같이 나뉘도록 3조각으로 잘랐어요. 조각들의 겉넓이의 합은 처음보다 몇 cm² 늘어났나요? 숫자로 쓰세요.","answer":["160"],"explanation":["2번 자르면 새 면이 2 × 2 = 4개 생겨요.","새 면 하나는 10 × 4 = 40, 40 × 4 = 160이에요.","그래서 160 cm² 늘어났어요."],"asset":{"type":"geo","items":[{"w":226.0,"h":110.6,"pts":{"ㄱ":[55.9,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,55.9,"w"],"ㄷ":[134.1,55.9,"sw"],"ㅁ":[55.9,44.7,"ne"],"ㅇ":[190.0,44.7,"e"],"ㅂ":[0,100.6,"sw"],"ㅅ":[134.1,100.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[67.0,113.6],"12 cm"],[[184.0,78.7],"10 cm"],[[216.0,22.4],"4 cm"]]}],"tag":false}},{"stem":"가로 9 cm, 세로 6 cm, 높이 4 cm인 두부를 가로가 똑같이 나뉘도록 3조각으로 잘랐어요. 조각들의 겉넓이의 합은 처음보다 몇 cm² 늘어났나요? 숫자로 쓰세요.","answer":["96"],"explanation":["2번 자르면 새 면이 2 × 2 = 4개 생겨요.","새 면 하나는 6 × 4 = 24, 24 × 4 = 96이에요.","그래서 96 cm² 늘어났어요."],"asset":{"type":"geo","items":[{"w":226.0,"h"