('g6_1_math_u6_L07_challenge#7','math',6,1,'u6','L07','g6_1_math_u6_L07_challenge','lesson_challenge','M6-1-u6-C7',3,'mc','auto','두부를 한 번 자르면 겉면이 새로 몇 개 생기나요?',ARRAY['M6-1-u6-X16']::text[],true,'{"seq":7,"concept":"M6-1-u6-C7","difficulty":3,"kind":"mc","stem":"두부를 한 번 자르면 겉면이 새로 몇 개 생기나요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"M6-1-u6-X16"},{"t":"4개","mis":"M6-1-u6-X16"},{"t":"생기지 않아요","mis":"M6-1-u6-X16"}],"explanation":["자른 조각을 도로 붙이면 처음 두부가 되므로 부피의 합은 그대로예요.","한 번 자를 때마다 자른 자리에 마주 보는 새 면 2개가 드러나요.","그래서 겉넓이는 자른 면만큼 늘어나요."],"variant_rule":{"alt":[{"stem":"직육면체 모양 두부를 자르면 겉넓이의 합은 어떻게 되나요?","options":[{"t":"자른 면만큼 늘어나요","correct":true},{"t":"그대로예요","mis":"M6-1-u6-X16"},{"t":"줄어들어요","mis":"M6-1-u6-X16"},{"t":"절반이 돼요","mis":"M6-1-u6-X15"}],"explanation":["자른 조각을 도로 붙이면 처음 두부가 되므로 부피의 합은 그대로예요.","한 번 자를 때마다 자른 자리에 마주 보는 새 면 2개가 드러나요.","그래서 겉넓이는 자른 면만큼 늘어나요."]},{"stem":"두부를 2조각, 4조각으로 자를 때 조각들의 부피의 합을 바르게 비교한 것은 어느 것인가요?","options":[{"t":"자르기 전과 2조각·4조각 모두 같아요","correct":true},{"t":"자를수록 커져요","mis":"M6-1-u6-X15"},{"t":"자를수록 작아져요","mis":"M6-1-u6-X15"},{"t":"알 수 없어요","mis":"M6-1-u6-X18"}],"explanation":["자른 조각을 도로 붙이면 처음 두부가 되므로 부피의 합은 그대로예요.","한 번 자를 때마다 자른 자리에 마주 보는 새 면 2개가 드러나요.","그래서 겉넓이는 자른 면만큼 늘어나요."]}]}}'::jsonb),
('g6_1_math_u6_L07_challenge#8','math',6,1,'u6','L07','g6_1_math_u6_L07_challenge','lesson_challenge','M6-1-u6-C7',4,'mc','auto','가로 10 cm, 세로 8 cm, 높이 5 cm인 두부를 똑같이 2조각으로 자를 때, 조각들의 겉넓이의 합이 가장 많이 늘어나는 방법은 어느 것인가요?',ARRAY['M6-1-u6-X16']::text[],true,'{"seq":8,"concept":"M6-1-u6-C7","difficulty":4,"kind":"mc","stem":"가로 10 cm, 세로 8 cm, 높이 5 cm인 두부를 똑같이 2조각으로 자를 때, 조각들의 겉넓이의 합이 가장 많이 늘어나는 방법은 어느 것인가요?","options":[{"t":"높이가 반이 되도록 자르기","correct":true},{"t":"가로가 반이 되도록 자르기","mis":"M6-1-u6-X16"},{"t":"세로가 반이 되도록 자르기","mis":"M6-1-u6-X16"},{"t":"어떻게 잘라도 똑같이 늘어나요","mis":"M6-1-u6-X16"}],"explanation":["늘어나는 겉넓이는 자른 면 2개의 넓이예요.","가로가 반이면 8 × 5 × 2 = 80, 세로가 반이면 10 × 5 × 2 = 100, 높이가 반이면 10 × 8 × 2 = 160이에요.","가장 넓은 면과 나란하게 자를 때 가장 많이 늘어나요."],"asset":{"type":"geo","items":[{"w":226.0,"h":132.2,"pts":{"ㄱ":[54.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,54.3,"w"],"ㄷ":[135.7,54.3,"sw"],"ㅁ":[54.3,67.9,"ne"],"ㅇ":[190.0,67.9,"e"],"ㅂ":[0,122.2,"sw"],"ㅅ":[135.7,122.2,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[67.8,135.2],"10 cm"],[[184.8,101.1],"8 cm"],[[216.0,34.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 12 cm, 세로 6 cm, 높이 4 cm인 두부를 똑같이 2조각으로 자를 때, 조각들의 겉넓이의 합이 가장 많이 늘어나는 방법은 어느 것인가요?","options":[{"t":"높이가 반이 되도록 자르기","correct":true},{"t":"가로가 반이 되도록 자르기","mis":"M6-1-u6-X16"},{"t":"세로가 반이 되도록 자르기","mis":"M6-1-u6-X16"},{"t":"어떻게 잘라도 똑같이 늘어나요","mis":"M6-1-u6-X16"}],"explanation":["늘어나는 겉넓이는 자른 면 2개의 넓이예요.","가로가 반이면 6 × 4 × 2 = 48, 세로가 반이면 12 × 4 × 2 = 96, 높이가 반이면 12 × 6 × 2 = 144예요.","가장 넓은 면과 나란하게 자를 때 가장 많이 늘어나요."],"asset":{"type":"geo","items":[{"w":226.0,"h":98.7,"pts":{"ㄱ":[38.0,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,38.0,"w"],"ㄷ":[152.0,38.0,"sw"],"ㅁ":[38.0,50.7,"ne"],"ㅇ":[190.0,50.7,"e"],"ㅂ":[0,88.7,"sw"],"ㅅ":[152.0,88.7,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ",