('g6_1_math_u6_L07_challenge#9','math',6,1,'u6','L07','g6_1_math_u6_L07_challenge','lesson_challenge','M6-1-u6-C7',4,'sa','auto','한 모서리가 4 cm인 정육면체 두부를 가로·세로·높이를 모두 반으로 잘라 작은 정육면체 8조각을 만들었어요. 8조각의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u6-C7","difficulty":4,"kind":"sa","stem":"한 모서리가 4 cm인 정육면체 두부를 가로·세로·높이를 모두 반으로 잘라 작은 정육면체 8조각을 만들었어요. 8조각의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["192"],"explanation":["작은 정육면체의 한 모서리는 2 cm이고 겉넓이는 2 × 2 × 6 = 24(cm²)예요.","8조각이므로 24 × 8 = 192예요.","처음 겉넓이 4 × 4 × 6 = 96의 2배예요. 그래서 192 cm²예요."],"mis":"M6-1-u6-X16","asset":{"type":"geo","items":[{"w":180.0,"h":154.0,"pts":{"ㄱ":[48.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,48.0,"w"],"ㄷ":[96.0,48.0,"sw"],"ㅁ":[48.0,96.0,"ne"],"ㅇ":[144.0,96.0,"e"],"ㅂ":[0,144.0,"sw"],"ㅅ":[96.0,144.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,157.0],"4 cm"],[[142.0,126.0],"4 cm"],[[170.0,48.0],"4 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 모서리가 6 cm인 정육면체 두부를 가로·세로·높이를 모두 반으로 잘라 작은 정육면체 8조각을 만들었어요. 8조각의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["432"],"explanation":["작은 정육면체의 한 모서리는 3 cm이고 겉넓이는 3 × 3 × 6 = 54(cm²)예요.","8조각이므로 54 × 8 = 432예요.","처음 겉넓이 6 × 6 × 6 = 216의 2배예요. 그래서 432 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":200.0,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,126.7,"ne"],"ㅇ":[190.0,126.7,"e"],"ㅂ":[0,190.0,"sw"],"ㅅ":[126.7,190.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,203.0],"6 cm"],[[180.3,164.3],"6 cm"],[[216.0,63.4],"6 cm"]]}],"tag":false}},{"stem":"한 모서리가 10 cm인 정육면체 두부를 가로·세로·높이를 모두 반으로 잘라 작은 정육면체 8조각을 만들었어요. 8조각의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["1200"],"explanation":["작은 정육면체의 한 모서리는 5 cm이고 겉넓이는 5 × 5 × 6 = 150(cm²)예요.","8조각이므로 150 × 8 = 1200이에요.","처음 겉넓이 10 × 10 × 6 = 600의 2배예요. 그래서 1200 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":200.0,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,126.7,"ne"],"ㅇ":[190.0,126.7,"e"],"ㅂ":[0,190.0,"sw"],"ㅅ":[126.7,190.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,203.0],"10 cm"],[[180.3,164.3],"10 cm"],[[216.0,63.4],"10 cm"]]}],"tag":false}}]}}'::jsonb),
('g6_1_math_u6_L07_challenge#10','math',6,1,'u6','L07','g6_1_math_u6_L07_challenge','lesson_challenge','M6-1-u6-C7',4,'essay','teacher','가로 10 cm, 세로 10 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 자르기 전과 비교하여 부피와 겉넓이가 각각 어떻게 되는지 셈과 함께 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u6-C7","difficulty":4,"kind":"essay","stem":"가로 10 cm, 세로 10 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 자르기 전과 비교하여 부피와 겉넓이가 각각 어떻게 되는지 셈과 함께 써 보세요.","answer_guide":{"answer":"예: 부피는 10 × 10 × 5 = 500(cm³)이고 두 조각을 더해도 250 + 250 = 500이므로 그대로다. 겉넓이는 처음 400 cm²에서 자른 면(10 × 5 = 50)이 2개 새로 생겨 400 + 50 × 2 = 500(cm²)으로 늘어난다.","scoring_points":["부피 500 cm³가 그대로라고 했는가","자른 면 50 cm²가 2개 생긴다고 했는가","겉넓이가 500 cm²로 늘어난다고 했는가"]},"explanation":["부피는 500 cm³ 그대로예요.","새 면 50 cm²가 2개 생겨요.","겉넓이는 400 + 100 = 500(cm²)이 돼요."]}'::jsonb),
('g6_1_math_u6_review_a#1','math',6,1,'u6','','g6_1_math_u6_review_a','unit_review','M6-1-u6-C1',1,'mc','auto','다음 중 부피를 알아야 하는 상황은 어느 것인가요?',ARRAY['M6-1-u6-X01']::text[],true,'{"seq":1,"concept":"M6-1-u6-C1","difficulty":1,"kind":"mc","stem":"다음 중 부피를 알아야 하는 상황은 어느 것인가요?","options":[{"t":"상자 안에 모래를 얼마나 담을지 알 때","correct":true},{"t":"상자에 포장지를 붙일 때","mis":"M6-1-u6-X01"},{"t":"상자의 겉면을 색칠할 때","mis":"M6-1-u6-X01"},{"t":"상자를 감쌀 종이를 살 때","mis":"M6-1-u6-X01"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「상자 안에 모래를 얼마나 담을지 알 때」예요."],"variant_rule":{"alt":[{"stem":"다음 중 겉넓이를 알아야 하는 상황은 어느 것인가요?","options":[{"t":"청사초롱 겉면에 붙일 한지의 양을 알 때","correct":true},{"t":"청사초롱 안에 담기는 공간의 크기를 알 때","mis":"M6-1-u6-X01"},{"t":"어항에 물을 얼마나 채울지 알 때","mis":"M6-1-u6-X01"},{"t":"상자에 쌓기나무를 몇 개 넣을지 알 때","mis":"M6-1-u6-X01"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「청사초롱 겉면에 붙일 한지의 양을 알 때」예요."]},{"stem":"선물 상자를 포장지로 겹치지 않게 감쌀 때 필요한 종이의 양과 관계있는 것은 어느 것인가요?","options":[{"t":"겉넓이","correct":true},{"t":"부피","mis":"M6-1-u6-X01"},{"t":"모서리의 수","mis":"M6-1-u6-X18"},{"t":"꼭짓점의 수","mis":"M6-1-u6-X18"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「겉넓이」예요."]}]}}'::jsonb),
('g6_1_math_u6_review_a#2','math',6,1,'u6','','g6_1_math_u6_review_a','unit_review','M6-1-u6-C4',1,'mc','auto','한 모서리가 1 cm인 정육면체의 부피를 무엇이라고 하나요?',ARRAY['M6-1-u6-X02']::text[],true,'{"seq":2,"concept":"M6-1-u6-C4","difficulty":1,"kind":"mc","stem":"한 모서리가 1 cm인 정육면체의 부피를 무엇이라고 하나요?","options":[{"t":"1 cm³","correct":true},{"t":"1 cm²","mis":"M6-1-u6-X02"},{"t":"1 cm","mis":"M6-1-u6-X02"},{"t":"3 cm","mis":"M6-1-u6-X02"}],"explanation":["부피의 표준 단위로 한 모서리가 1 cm인 정육면체를 써요.","그 부피를 1 cm³라 쓰고 「1 세제곱센티미터」라고 읽어요.","정답은 「1 cm³」예요."],"variant_rule":{"alt":[{"stem":"「1 cm³」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1 세제곱센티미터","correct":true},{"t":"1 제곱센티미터","mis":"M6-1-u6-X02"},{"t":"1 센티미터","mis":"M6-1-u6-X02"},{"t":"3 센티미터","mis":"M6-1-u6-X02"}],"explanation":["부피의 표준 단위로 한 모서리가 1 cm인 정육면체를 써요.","그 부피를 1 cm³라 쓰고 「1 세제곱센티미터」라고 읽어요.","정답은 「1 세제곱센티미터」예요."]},{"stem":"한 모서리가 1 m인 정육면체의 부피를 무엇이라고 하나요?","options":[{"t":"1 m³","correct":true},{"t":"1 m²","mis":"M6-1-u6-X02"},{"t":"1 cm³","mis":"M6-1-u6-X13"},{"t":"100 cm³","mis":"M6-1-u6-X13"}],"explanation":["한 모서리가 1 m인 정육면체의 부피를 1 m³라 쓰고 「1 세제곱미터」라고 읽어요.","1 m = 100 cm이므로 100 × 100 × 100 = 1000000이에요.","정답은 「1 m³」예요."]}]}}'::jsonb),
('g6_1_math_u6_review_a#3','math',6,1,'u6','','g6_1_math_u6_review_a','unit_review','M6-1-u6-C3',1,'mc','auto','정육면체의 겉넓이를 구하는 바른 방법은 어느 것인가요?',ARRAY['M6-1-u6-X06','M6-1-u6-X04']::text[],true,'{"seq":3,"concept":"M6-1-u6-C3","difficulty":1,"kind":"mc","stem":"정육면체의 겉넓이를 구하는 바른 방법은 어느 것인가요?","options":[{"t":"한 면의 넓이 × 6","correct":true},{"t":"한 면의 넓이 × 4","mis":"M6-1-u6-X06"},{"t":"한 모서리 × 6","mis":"M6-1-u6-X06"},{"t":"한 면의 넓이 × 2","mis":"M6-1-u6-X04"}],"explanation":["정육면체는 여섯 면이 모두 합동인 정사각형이에요.","그래서 한 면의 넓이만 구해 6배 하면 겉넓이예요.","정답은 「한 면의 넓이 × 6」이에요."],"variant_rule":{"alt":[{"stem":"직육면체의 부피를 구하는 바른 식은 어느 것인가요?","options":[{"t":"(가로) × (세로) × (높이)","correct":true},{"t":"(가로) + (세로) + (높이)","mis":"M6-1-u6-X11"},{"t":"(가로) × (세로)","mis":"M6-1-u6-X11"},{"t":"(가로) × (세로) × (높이) × 2","mis":"M6-1-u6-X18"}],"explanation":["가로·세로·높이에 놓이는 1 cm³ 쌓기나무의 개수는 각 모서리의 길이와 같아요.","세 개수를 곱하면 전체 개수, 곧 부피예요.","정답은 「(가로) × (세로) × (높이)」예요."]},{"stem":"정육면체의 부피를 구하는 바른 식은 어느 것인가요?","options":[{"t":"(한 모서리) × (한 모서리) × (한 모서리)","correct":true},{"t":"(한 모서리) × 3","mis":"M6-1-u6-X12"},{"t":"(한 모서리) × (한 모서리) × 6","mis":"M6-1-u6-X12"},{"t":"(한 모서리) × (한 모서리)","mis":"M6-1-u6-X11"}],"explanation":["가로·세로·높이에 놓이는 1 cm³ 쌓기나무의 개수는 각 모서리의 길이와 같아요.","세 개수를 곱하면 전체 개수, 곧 부피예요.","정답은 「(한 모서리) × (한 모서리) × (한 모서리)」예요."]}]}}'::jsonb),
('g6_1_math_u6_review_a#4','math',6,1,'u6','','g6_1_math_u6_review_a','unit_review','M6-1-u6-C1',1,'ox','auto','겉넓이는 상자를 감싸는 종이의 양이고, 부피는 상자 안에 담기는 공간의 크기예요.',ARRAY['M6-1-u6-X01']::text[],true,'{"seq":4,"concept":"M6-1-u6-C1","difficulty":1,"kind":"ox","stem":"겉넓이는 상자를 감싸는 종이의 양이고, 부피는 상자 안에 담기는 공간의 크기예요.","answer":"O","reason_options":[{"t":"겉면의 넓이와 공간의 크기는 서로 다른 양이기 때문에","correct":true},{"t":"둘 다 상자의 크기라서 같은 양이기 때문에","mis":"M6-1-u6-X01"}],"mis":"M6-1-u6-X01","explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."],"variant_rule":{"alt":[{"stem":"직육면체의 겉넓이는 겨냥도에 보이는 세 면의 넓이를 더한 것이에요.","answer":"X","reason_options":[{"t":"겉넓이는 보이지 않는 면까지 여섯 면 전부의 넓이이기 때문에","correct":true},{"t":"보이지 않는 면은 겉면이 아니기 때문에","mis":"M6-1-u6-X03"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 세 면의 합 × 2로도 구해요.","단위는 넓이 단위 cm²를 써요."]},{"stem":"직육면체의 부피는 가로, 세로, 높이를 모두 더해서 구해요.","answer":"X","reason_options":[{"t":"부피는 세 길이를 곱해서 구하기 때문에","correct":true},{"t":"세 길이를 더하면 쌓기나무 개수가 되기 때문에","mis":"M6-1-u6-X11"}],"explanation":["부피 = 가로 × 세로 × 높이 = 한 밑면의 넓이 × 높이예요.","정육면체는 한 모서리를 세 번 곱해요.","부피와 겉넓이는 서로 다른 양이에요."]}]}}'::jsonb),
('g6_1_math_u6_review_a#5','math',6,1,'u6','','g6_1_math_u6_review_a','unit_review','M6-1-u6-C4',1,'sa','auto','부피가 1 cm³인 쌓기나무 5개로 쌓은 도형의 부피는 몇 cm³인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u6-C4","difficulty":1,"kind":"sa","stem":"부피가 1 cm³인 쌓기나무 5개로 쌓은 도형의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["1 cm³인 쌓기나무 한 개의 부피가 1 cm³예요.","5개이면 1 × 5 = 5예요.","그래서 5 cm³예요."],"mis":"M6-1-u6-X10","variant_rule":{"alt":[{"stem":"부피가 1 cm³인 쌓기나무 9개로 쌓은 도형의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["1 cm³인 쌓기나무 한 개의 부피가 1 cm³예요.","9개이면 1 × 9 = 9예요.","그래서 9 cm³예요."]},{"stem":"부피가 1 cm³인 쌓기나무 12개로 쌓은 도형의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["1 cm³인 쌓기나무 한 개의 부피가 1 cm³예요.","12개이면 1 × 12 = 12예요.","그래서 12 cm³예요."]}]}}'::jsonb),
('g6_1_math_u6_review_a#6','math',6,1,'u6','','g6_1_math_u6_review_a','unit_review','M6-1-u6-C6',1,'mc','auto','1 m³는 몇 cm³인가요?',ARRAY['M6-1-u6-X13']::text[],true,'{"seq":6,"concept":"M6-1-u6-C6","difficulty":1,"kind":"mc","stem":"1 m³는 몇 cm³인가요?","options":[{"t":"1000000 cm³","correct":true},{"t":"100 cm³","mis":"M6-1-u6-X13"},{"t":"10000 cm³","mis":"M6-1-u6-X13"},{"t":"1000 cm³","mis":"M6-1-u6-X13"}],"explanation":["1 m = 100 cm이므로 1 m³는 한 모서리 100 cm인 정육면체예요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","그래서 1 m³는 1000000 cm³예요."],"variant_rule":{"alt":[{"stem":"3 m³는 몇 cm³인가요?","options":[{"t":"3000000 cm³","correct":true},{"t":"300 cm³","mis":"M6-1-u6-X13"},{"t":"30000 cm³","mis":"M6-1-u6-X13"},{"t":"3000 cm³","mis":"M6-1-u6-X13"}],"explanation":["1 m = 100 cm이므로 1 m³는 한 모서리 100 cm인 정육면체예요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","1000000 × 3 = 3000000이므로 3000000 cm³예요."]},{"stem":"6 m³는 몇 cm³인가요?","options":[{"t":"6000000 cm³","correct":true},{"t":"600 cm³","mis":"M6-1-u6-X13"},{"t":"60000 cm³","mis":"M6-1-u6-X13"},{"t":"6000 cm³","mis":"M6-1-u6-X13"}],"explanation":["1 m = 100 cm이므로 1 m³는 한 모서리 100 cm인 정육면체예요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","1000000 × 6 = 6000000이므로 6000000 cm³예요."]}]}}'::jsonb),
('g6_1_math_u6_review_a#7','math',6,1,'u6','','g6_1_math_u6_review_a','unit_review','M6-1-u6-C7',1,'mc','auto','직육면체 모양 두부를 똑같이 2조각으로 자르면 두 조각의 부피의 합은 어떻게 되나요?',ARRAY['M6-1-u6-X15','M6-1-u6-X16']::text[],true,'{"seq":7,"concept":"M6-1-u6-C7","difficulty":1,"kind":"mc","stem":"직육면체 모양 두부를 똑같이 2조각으로 자르면 두 조각의 부피의 합은 어떻게 되나요?","options":[{"t":"자르기 전과 같아요","correct":true},{"t":"절반으로 줄어요","mis":"M6-1-u6-X15"},{"t":"두 배가 돼요","mis":"M6-1-u6-X15"},{"t":"자른 면만큼 늘어나요","mis":"M6-1-u6-X16"}],"explanation":["자른 조각을 도로 붙이면 처음 두부가 되므로 부피의 합은 그대로예요.","한 번 자를 때마다 자른 자리에 마주 보는 새 면 2개가 드러나요.","그래서 겉넓이는 자른 면만큼 늘어나요."],"variant_rule":{"alt":[{"stem":"직육면체 모양 두부를 자르면 겉넓이의 합은 어떻게 되나요?","options":[{"t":"자른 면만큼 늘어나요","correct":true},{"t":"그대로예요","mis":"M6-1-u6-X16"},{"t":"줄어들어요","mis":"M6-1-u6-X16"},{"t":"절반이 돼요","mis":"M6-1-u6-X15"}],"explanation":["자른 조각을 도로 붙이면 처음 두부가 되므로 부피의 합은 그대로예요.","한 번 자를 때마다 자른 자리에 마주 보는 새 면 2개가 드러나요.","그래서 겉넓이는 자른 면만큼 늘어나요."]},{"stem":"두부를 2조각, 4조각으로 자를 때 조각들의 부피의 합을 바르게 비교한 것은 어느 것인가요?","options":[{"t":"자르기 전과 2조각·4조각 모두 같아요","correct":true},{"t":"자를수록 커져요","mis":"M6-1-u6-X15"},{"t":"자를수록 작아져요","mis":"M6-1-u6-X15"},{"t":"알 수 없어요","mis":"M6-1-u6-X18"}],"explanation":["자른 조각을 도로 붙이면 처음 두부가 되므로 부피의 합은 그대로예요.","한 번 자를 때마다 자른 자리에 마주 보는 새 면 2개가 드러나요.","그래서 겉넓이는 자른 면만큼 늘어나요."]}]}}'::jsonb),
