('g6_1_math_u6_review_a#15','math',6,1,'u6','','g6_1_math_u6_review_a','unit_review','M6-1-u6-C6',2,'mc','auto','넓이 1 m²와 부피 1 m³를 cm 단위로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u6-X13','M6-1-u6-X02']::text[],true,'{"seq":15,"concept":"M6-1-u6-C6","difficulty":2,"kind":"mc","stem":"넓이 1 m²와 부피 1 m³를 cm 단위로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1 m² = 10000 cm², 1 m³ = 1000000 cm³","correct":true},{"t":"1 m² = 10000 cm², 1 m³ = 10000 cm³","mis":"M6-1-u6-X13"},{"t":"1 m² = 100 cm², 1 m³ = 1000 cm³","mis":"M6-1-u6-X13"},{"t":"1 m² = 1000000 cm², 1 m³ = 10000 cm³","mis":"M6-1-u6-X02"}],"explanation":["넓이는 두 방향을 곱해 1 m² = 100 × 100 = 10000(cm²)예요.","부피는 세 방향을 곱해 1 m³ = 100 × 100 × 100 = 1000000(cm³)예요.","정답은 「1 m² = 10000 cm², 1 m³ = 1000000 cm³」예요."],"variant_rule":{"alt":[{"stem":"100 × 100 × 100으로 구하는 것은 어느 것인가요?","options":[{"t":"1 m³가 몇 cm³인지","correct":true},{"t":"1 m²가 몇 cm²인지","mis":"M6-1-u6-X02"},{"t":"1 m가 몇 cm인지","mis":"M6-1-u6-X13"},{"t":"1 cm³가 몇 m³인지","mis":"M6-1-u6-X14"}],"explanation":["넓이는 두 방향을 곱해 1 m² = 100 × 100 = 10000(cm²)예요.","부피는 세 방향을 곱해 1 m³ = 100 × 100 × 100 = 1000000(cm³)예요.","정답은 「1 m³가 몇 cm³인지」예요."]},{"stem":"다음 중 부피를 m³로 나타내기에 알맞은 것은 어느 것인가요?","options":[{"t":"교실","correct":true},{"t":"주사위","mis":"M6-1-u6-X14"},{"t":"각설탕","mis":"M6-1-u6-X14"},{"t":"지우개","mis":"M6-1-u6-X14"}],"explanation":["작은 물건의 부피는 cm³로 나타내요.","방·교실·트럭 짐칸·컨테이너처럼 큰 것은 m³로 나타내는 것이 편해요.","정답은 「교실」이에요."]}]}}'::jsonb),
