 같아도 겉넓이는 다를 수 있어요."],"asset":{"type":"geo","items":[{"w":226.0,"h":200.0,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,126.7,"ne"],"ㅇ":[190.0,126.7,"e"],"ㅂ":[0,190.0,"sw"],"ㅅ":[126.7,190.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,203.0],"6 cm"],[[180.3,164.3],"6 cm"],[[216.0,63.4],"6 cm"]],"cap":"가"},{"w":226.0,"h":86.0,"pts":{"ㄱ":[38.0,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,38.0,"w"],"ㄷ":[152.0,38.0,"sw"],"ㅁ":[38.0,38.0,"ne"],"ㅇ":[190.0,38.0,"e"],"ㅂ":[0,76.0,"sw"],"ㅅ":[152.0,76.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[76.0,89.0],"12 cm"],[[193.0,63.0],"6 cm"],[[216.0,19.0],"3 cm"]],"cap":"나"}],"tag":false}},{"stem":"직육면체 가는 가로 2 cm, 세로 2 cm, 높이 8 cm, 나는 가로 4 cm, 세로 4 cm, 높이 2 cm예요. 옳은 것은 어느 것인가요?","options":[{"t":"부피는 같지만 겉넓이는 달라요","correct":true},{"t":"부피가 같으니 겉넓이도 같아요","mis":"M6-1-u6-X17"},{"t":"겉넓이가 다르니 부피도 달라요","mis":"M6-1-u6-X17"},{"t":"부피도 겉넓이도 달라요","mis":"M6-1-u6-X18"}],"explanation":["가의 부피는 2 × 2 × 8 = 32, 나의 부피는 4 × 4 × 2 = 32(cm³)예요.","가의 겉넓이는 72, 나의 겉넓이는 64(cm²)예요.","부피가 같아도 겉넓이는 다를 수 있어요."],"asset":{"type":"geo","items":[{"w":92.3,"h":178.8,"pts":{"ㄱ":[18.8,0,"nw"],"ㄹ":[56.3,0,"ne"],"ㄴ":[0,18.8,"w"],"ㄷ":[37.5,18.8,"sw"],"ㅁ":[18.8,150.0,"ne"],"ㅇ":[56.3,150.0,"e"],"ㅂ":[0,168.8,"sw"],"ㅅ":[37.5,168.8,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[18.8,181.8],"2 cm"],[[68.9,165.4],"2 cm"],[[82.3,75.0],"8 cm"]],"cap":"가"},{"w":180.0,"h":106.0,"pts":{"ㄱ":[48.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,48.0,"w"],"ㄷ":[96.0,48.0,"sw"],"ㅁ":[48.0,48.0,"ne"],"ㅇ":[144.0,48.0,"e"],"ㅂ":[0,96.0,"sw"],"ㅅ":[96.0,96.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],