"부피가 같아도 겉넓이는 다를 수 있어요."],"asset":{"type":"geo","items":[{"w":180.0,"h":154.0,"pts":{"ㄱ":[48.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,48.0,"w"],"ㄷ":[96.0,48.0,"sw"],"ㅁ":[48.0,96.0,"ne"],"ㅇ":[144.0,96.0,"e"],"ㅂ":[0,144.0,"sw"],"ㅅ":[96.0,144.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,157.0],"4 cm"],[[142.0,126.0],"4 cm"],[[170.0,48.0],"4 cm"]],"cap":"가"},{"w":226.0,"h":86.0,"pts":{"ㄱ":[38.0,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,38.0,"w"],"ㄷ":[152.0,38.0,"sw"],"ㅁ":[38.0,38.0,"ne"],"ㅇ":[190.0,38.0,"e"],"ㅂ":[0,76.0,"sw"],"ㅅ":[152.0,76.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[76.0,89.0],"8 cm"],[[193.0,63.0],"4 cm"],[[216.0,19.0],"2 cm"]],"cap":"나"}],"tag":false}},{"stem":"직육면체 가는 가로 6 cm, 세로 6 cm, 높이 6 cm, 나는 가로 12 cm, 세로 6 cm, 높이 3 cm예요. 옳은 것은 어느 것인가요?","options":[{"t":"부피는 같지만 겉넓이는 달라요","correct":true},{"t":"부피가 같으니 겉넓이도 같아요","mis":"M6-1-u6-X17"},{"t":"겉넓이가 다르니 부피도 달라요","mis":"M6-1-u6-X17"},{"t":"부피도 겉넓이도 달라요","mis":"M6-1-u6-X18"}],"explanation":["가의 부피는 6 × 6 × 6 = 216, 나의 부피는 12 × 6 × 3 = 216(cm³)예요.","가의 겉넓이는 216, 나의 겉넓이는 252(cm²)예요.","부피가 같아도 겉넓이는 다를 수 있어요."],"asset":{"type":"geo","items":[{"w":226.0,"h":200.0,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,126.7,"ne"],"ㅇ":[190.0,126.7,"e"],"ㅂ":[0,190.0,"sw"],"ㅅ":[126.7,190.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,203.0],"6 cm"],[[180.3,164.3],"6 cm"],[[216.0,63.4],"6 cm"]],"cap":"가"},{"w":226.0,"h":86.0,"pts":{"ㄱ":[38.0,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,38.0,"w"],"ㄷ":[152.0,38.0,"sw"],"ㅁ":[38.0,38.0,"ne"],"ㅇ":[190.0,38.0,"e"],"ㅂ":[0,76.0,"sw"],"ㅅ":[152.0,76.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[76.0,89.0],"12 cm"],[[193.0,63.0],"6 cm"],[[216.0,19.0],"3 cm"]],"cap":"나"}],"tag":false}}]}}'::jsonb),
('g6_1_math_u6_review_d#23','math',6,1,'u6','','g6_1_math_u6_review_d','unit_review','M6-1-u6-C5',4,'sa','auto','가로 12 cm, 세로 8 cm, 높이 6 cm인 직육면체 모양 상자에 한 모서리가 2 cm인 정육면체 블록을 빈틈없이 채우려고 해요. 블록은 모두 몇 개 들어가나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u6-C5","difficulty":4,"kind":"sa","stem":"가로 12 cm, 세로 8 cm, 높이 6 cm인 직육면체 모양 상자에 한 모서리가 2 cm인 정육면체 블록을 빈틈없이 채우려고 해요. 블록은 모두 몇 개 들어가나요? 숫자로 쓰세요.","answer":["72"],"explanation":["가로에 12 ÷ 2 = 6개, 세로에 8 ÷ 2 = 4개, 높이에 6 ÷ 2 = 3개가 놓여요.","6 × 4 × 3 = 72예요.","그래서 72개예요."],"mis":"M6-1-u6-X10","asset":{"type":"geo","items":[{"w":226.0,"h":128.7,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,71.2,"ne"],"ㅇ":[190.0,71.2,"e"],"ㅂ":[0,118.7,"sw"],"ㅅ":[142.5,118.7,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[71.2,131.7],"12 cm"],[[188.2,101.0],"8 cm"],[[216.0,35.6],"6 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 2 m, 세로 150 cm, 높이 100 cm인 직육면체 모양 창고의 부피는 몇 m³인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["단위를 m로 맞춰요: 150 cm = 1.5 m, 100 cm = 1 m예요.","2 × 1.5 × 1 = 3이에요.","그래서 3 m³예요."]},{"stem":"겉넓이가 294 cm²인 정육면체가 있어요. 한 모서리는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 면의 넓이는 294 ÷ 6 = 49예요.","같은 수를 두 번 곱해 49가 되는 수는 7 × 7 = 49이므로 7이에요.","그래서 한 모서리는 7 cm예요."]}]}}'::jsonb),
('g6_1_math_u6_review_d#24','math',6,1,'u6','','g6_1_math_u6_review_d','unit_review','M6-1-u6-C7',4,'essay','teacher','가로 10 cm, 세로 10 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 자르기 전과 비교하여 부피와 겉넓이가 각각 어떻게 되는지 셈과 함께 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u6-C7","difficulty":4,"kind":"essay","stem":"가로 10 cm, 세로 10 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 자르기 전과 비교하여 부피와 겉넓이가 각각 어떻게 되는지 셈과 함께 써 보세요.","answer_guide":{"answer":"예: 부피는 10 × 10 × 5 = 500(cm³)이고 두 조각을 더해도 250 + 250 = 500이므로 그대로다. 겉넓이는 처음 400 cm²에서 자른 면(10 × 5 = 50)이 2개 새로 생겨 400 + 50 × 2 = 500(cm²)으로 늘어난다.","scoring_points":["부피 500 cm³가 그대로라고 했는가","자른 면 50 cm²가 2개 생긴다고 했는가","겉넓이가 500 cm²로 늘어난다고 했는가"]},"explanation":["부피는 500 cm³ 그대로예요.","새 면 50 cm²가 2개 생겨요.","겉넓이는 400 + 100 = 500(cm²)이 돼요."]}'::jsonb),
('g6_1_math_u6_review_d#25','math',6,1,'u6','','g6_1_math_u6_review_d','unit_review','M6-1-u6-C1',4,'essay','teacher','여울이는 「겉면이 넓은 상자가 언제나 더 많이 담긴다.」고 말했어요. 이 말이 맞는지 판단하고, 겉넓이와 부피가 어떤 양인지 넣어 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u6-C1","difficulty":4,"kind":"essay","stem":"여울이는 「겉면이 넓은 상자가 언제나 더 많이 담긴다.」고 말했어요. 이 말이 맞는지 판단하고, 겉넓이와 부피가 어떤 양인지 넣어 까닭을 써 보세요.","answer_guide":{"answer":"예: 맞지 않다. 겉넓이는 상자를 감싸는 종이의 양(겉면의 넓이)이고 부피는 상자 안에 담기는 공간의 크기라서 서로 다른 양이다. 그래서 겉면이 넓어도 담기는 양은 더 적을 수 있다.","scoring_points":["맞지 않다고 판단했는가","겉넓이 = 겉면의 넓이(감싸는 양)라고 썼는가","부피 = 담기는 공간의 크기라고 쓰고 두 양이 다르다고 설명했는가"]},"explanation":["겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요.","그래서 겉면이 넓다고 언제나 더 많이 담기지는 않아요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SC6-1-u1-C1','sci',6,1,'u1',1,'보물 찾기 활동 — 『과학』 놀이공원 지도에서 보물을 숨길 장소를 정하고, 그 장소에는 제빵 소다 용액을 한 방울, 나머지 장소에는 물을 떨어뜨림(맨눈으로 구별할 수 없도록 비슷한 양) · 마르면 친구와 지도를 바꾸고 숨긴 곳을 예상해 페놀프탈레인 용액을 한 방울 떨어뜨림 · 못 찾으면 다시 예상하고 확인 · 유리 기구 조심, 함부로 맛보거나 냄새 맡지 않기, 피부·눈에 튀지 않게(들어가면 흐르는 물로), 끝나면 정리 · 빨리 찾는 경쟁보다 색깔 변화 관찰에 집중',ARRAY['여러 가지 용액을 관찰하여 분류하고, 지시약을 이용하여 산성 용액과 염기성 용액으로 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],1),
('SC6-1-u1-C2','sci',6,1,'u1',1,'용액을 섞을 때의 색깔 변화 — 제빵 소다 용액을 떨어뜨린 곳에 페놀프탈레인 용액을 떨어뜨리면 붉은색으로 변하고, 물을 떨어뜨린 곳에서는 아무 변화가 없음 · 용액을 섞으면 다른 색깔로 변하는 경우도 있고 변하지 않는 경우도 있음 · 그 색깔 변화를 이용해 보물을 숨긴 곳을 찾을 수 있음 · 왜 색깔이 변하는지는 다음 시간부터 알아봄',ARRAY['여러 가지 용액을 관찰하여 분류하고, 지시약을 이용하여 산성 용액과 염기성 용액으로 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],2),
('SC6-1-u1-C3','sci',6,1,'u1',2,'여러 가지 용액의 관찰 — 점적병에 담긴 식초(노란색·투명·냄새), 레몬즙(연한 노란색·불투명·냄새), 빨랫비누 물(흰색·불투명·흔들면 거품 유지·냄새), 석회수(색깔 없음·투명·냄새 안 남), 묽은 염산(색깔 없음·투명·자극성이 강해 냄새를 맡지 않음), 묽은 수산화 나트륨 용액(색깔 없음·투명·냄새 안 남) · 색깔은 흰 종이를, 투명한 정도는 글씨가 쓰인 흰 종이를 뒤에 대고 관찰 · 냄새는 손으로 바람을 일으켜 맡음 · 실험복·보안경·실험용 장갑, 맛보거나 맨손으로 만지지 않기',ARRAY['여러 가지 용액을 관찰하여 분류하고, 지시약을 이용하여 산성 용액과 염기성 용액으로 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],3),
('SC6-1-u1-C4','sci',6,1,'u1',2,'투명하다와 색깔이 없다 — 「투명하다」는 속까지 환히 비치도록 맑다는 뜻으로 「색깔이 없다」와는 다른 뜻 · 식초처럼 색깔이 있어도 투명한 용액이 있음 · 석회수는 색깔이 없고 투명함',ARRAY['여러 가지 용액을 관찰하여 분류하고, 지시약을 이용하여 산성 용액과 염기성 용액으로 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],4),
('SC6-1-u1-C5','sci',6,1,'u1',2,'분류 기준 세우기 — 용액을 관찰해 비슷한 점과 다른 점을 찾아 분류 기준을 정하고 분류함 · 분류 기준은 객관적이고 명확한 질문(「색깔이 있는가?」, 「투명한가?」, 「흔들었을 때 거품이 5초 이상 유지되는가?」) · 「용액이 예쁜가?」처럼 사람마다 다르게 판단하는 기준은 알맞지 않음 · 알맞은 기준이면 누가 분류해도 결과가 같음 · 겉보기 성질이 비슷한 용액은 쉽게 구분되지 않아 분류하기 어려움',ARRAY['여러 가지 용액을 관찰하여 분류하고, 지시약을 이용하여 산성 용액과 염기성 용액으로 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],5),
