('SC6-1-u1-C19','sci',6,1,'u1',7,'산성화 — 어떤 물질이 기존의 성질에서 점차 산성으로 변하는 것 · 산성비: 보통 때보다 산성을 띠는 비(대기 중의 오염 물질이 빗물에 녹음) · 해양 산성화: 바닷물이 산성을 띠는 현상(주된 원인은 이산화 탄소) · 토양 산성화: 땅(흙)이 산성을 띠는 현상',ARRAY['우리 생활에서 산성 용액과 염기성 용액을 이용하는 예를 찾고, 산성화가 환경에 미치는 영향을 조사·공유(문구 초안 — 성취기준 코드 W7 확인)']::text[],19),
('SC6-1-u1-C20','sci',6,1,'u1',7,'산성화로 인한 피해 — 산성비: 삼림 황폐, 대리암으로 만든 조각상·건축물 훼손(대리암의 주요 성분인 탄산 칼슘이 산성 용액에 녹음), 호수·강의 어류·플랑크톤 피해 · 해양 산성화: 조개껍데기가 얇아짐, 산호가 잘 자라지 못함(조개껍데기·산호의 주요 성분인 탄산 칼슘), 해양 생물 다양성 감소 · 산호초 백화 현상은 해수온 상승·해양 산성화·염분 농도 변화·유해 물질 등 여러 원인 · 토양 산성화: 식물 생장 억제, 토양 미생물 활동 저하 · 생태계를 파괴하고 건물과 문화재도 훼손',ARRAY['우리 생활에서 산성 용액과 염기성 용액을 이용하는 예를 찾고, 산성화가 환경에 미치는 영향을 조사·공유(문구 초안 — 성취기준 코드 W7 확인)']::text[],20),
('SC6-1-u1-C21','sci',6,1,'u1',7,'산성화의 원인과 대책 — 원인: 화석 연료의 연소, 자동차 배기가스, 산업 활동 등 사람의 활동, 화학 비료나 농약의 과도한 사용 · 대책: 친환경 에너지 이용, 자전거·대중교통 이용으로 대기로 나가는 오염 물질과 이산화 탄소 줄이기 · 산성화된 호수에 염기성 물질을 뿌리면 산성이 약해짐 · 산성화는 전 세계적으로 발생하는 환경 문제로 우리와 관계있음',ARRAY['우리 생활에서 산성 용액과 염기성 용액을 이용하는 예를 찾고, 산성화가 환경에 미치는 영향을 조사·공유(문구 초안 — 성취기준 코드 W7 확인)']::text[],21),
('SC6-1-u1-C22','sci',6,1,'u1',8,'산성화 알림 동영상 — ① 조사해요: 모둠별로 주제(산성비·해양 산성화·토양 산성화 등)를 고르고 역할을 나누어 원인·현황·전망·대책 조사 → ② 계획해요: 제작 방법과 넣을 내용 협의 → ③ 만들어요: 동영상 편집 애플리케이션 → ④ 공유해요: 누리망·사회 관계망 서비스에 올리고 다른 모둠 동영상에 잘한 점을 댓글로 · 목적: 피해 사례를 소개하고 산성화를 줄이는 노력에 함께하도록 알림 · 자료를 공유할 때는 출처를 밝히거나 인터넷 주소를 링크로 연결(저작권·출처 존중)',ARRAY['우리 생활에서 산성 용액과 염기성 용액을 이용하는 예를 찾고, 산성화가 환경에 미치는 영향을 조사·공유(문구 초안 — 성취기준 코드 W7 확인)']::text[],22),
('SC6-1-u1-C23','sci',6,1,'u1',8,'환경 과학자 — 토양, 공기, 물 등을 조사하고 분석하여 산성화와 같은 환경 문제의 원인을 찾고 개선하기 위해 연구함 · 토양 환경 과학자: 토양의 산성도 등 상태 분석, 식물이 잘 자랄 환경 연구, 화학 비료·농약을 줄이는 방법과 친환경 퇴비 안내, 토양 오염을 줄이는 기술 개발 · 대기 환경 과학자: 대기 상태 측정·분석, 산성 대기 오염 물질 검출과 배출원 파악, 깨끗한 대기 환경을 위해 노력 · 수질 환경 과학자: 하천·저수지·호수의 수질 측정, 물의 온도·산성도를 재어 호수·해양 산성화와 수질 오염의 원인 파악, 수질 정화 방법 연구',ARRAY['우리 생활에서 산성 용액과 염기성 용액을 이용하는 예를 찾고, 산성화가 환경에 미치는 영향을 조사·공유(문구 초안 — 성취기준 코드 W7 확인)']::text[],23)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SC6-1-u1-X01','sci',6,'u1',ARRAY['SC6-1-u1-C1','SC6-1-u1-C2']::text[],'보물을 숨긴 곳과 숨기지 않은 곳의 결과를 뒤바꾸거나, 물이 페놀프탈레인 용액을 붉게 만든다고 여긴다','붉어진 곳은 제빵 소다 용액 자리'),
('SC6-1-u1-X02','sci',6,'u1',ARRAY['SC6-1-u1-C1']::text[],'보물 찾기 활동의 순서·방법·안전을 잘못 안다(양을 다르게 떨어뜨리기, 마르기 전에 바꾸기, 맛보기, 빨리 찾는 경쟁에만 매달리기 등)','비슷한 양 · 마른 뒤 바꾸기 · 맛보지 않기'),
('SC6-1-u1-X03','sci',6,'u1',ARRAY['SC6-1-u1-C2']::text[],'용액을 섞으면 언제나 색깔이 변한다고, 또는 결코 변하지 않는다고 여긴다','변하기도 하고 변하지 않기도 해요'),
('SC6-1-u1-X04','sci',6,'u1',ARRAY['SC6-1-u1-C3','SC6-1-u1-C9','SC6-1-u1-C12']::text[],'용액을 관찰하거나 실험할 때 지킬 것을 잘못 안다(맛보기, 코를 대고 냄새 맡기, 묽은 염산 냄새 맡기, 맨손으로 만지기, 보호 장비 없이 하기 등)','손으로 바람 · 보안경·장갑 · 맛보지 않기'),
('SC6-1-u1-X05','sci',6,'u1',ARRAY['SC6-1-u1-C3']::text[],'여섯 가지 용액의 관찰 결과(색깔·투명한 정도·거품·냄새)를 서로 바꾸어 안다','관찰 기록을 다시 읽어요'),
('SC6-1-u1-X06','sci',6,'u1',ARRAY['SC6-1-u1-C4']::text[],'투명한 용액은 색깔이 없다고 여기거나, 색깔이 있는 용액은 모두 불투명하다고 여긴다','식초는 노란색인데 투명해요'),
('SC6-1-u1-X07','sci',6,'u1',ARRAY['SC6-1-u1-C5']::text[],'분류 기준을 「예쁜가?」, 「마음에 드는가?」처럼 사람마다 다르게 판단하는 질문으로 세운다','객관적이고 명확한 질문'),
('SC6-1-u1-X08','sci',6,'u1',ARRAY['SC6-1-u1-C5','SC6-1-u1-C6']::text[],'겉보기 성질만으로 모든 용액을 나눌 수 있다고 여기거나, 색깔이 없고 투명한 용액은 지시약으로도 나눌 수 없다고 여긴다','겉보기가 비슷하면 지시약을 써요'),
('SC6-1-u1-X09','sci',6,'u1',ARRAY['SC6-1-u1-C6']::text[],'지시약의 뜻을 잘못 안다(쇠붙이를 끌어당기는 물질, 빛을 내는 물질, 온도에 따라 어는 물질 등으로)','성질에 따라 색깔이 변하는 물질'),
('SC6-1-u1-X10','sci',6,'u1',ARRAY['SC6-1-u1-C6','SC6-1-u1-C9']::text[],'지시약은 한 종류뿐이라고 여기거나, 어느 지시약이든 같은 용액에서 같은 색으로 변한다고 여긴다','지시약마다 색깔 변화가 달라요'),
('SC6-1-u1-X11','sci',6,'u1',ARRAY['SC6-1-u1-C7']::text[],'푸른색·붉은색 리트머스 시험지가 어느 용액에서 어떤 색으로 변하는지 거꾸로 안다','푸른색은 산성에서 붉게, 붉은색은 염기성에서 푸르게'),
('SC6-1-u1-X12','sci',6,'u1',ARRAY['SC6-1-u1-C7']::text[],'페놀프탈레인 용액이 산성 용액에서 붉은색으로 변한다고, 또는 두 용액 모두에서 변한다고 여긴다','염기성에서만 붉은색'),
('SC6-1-u1-X13','sci',6,'u1',ARRAY['SC6-1-u1-C8']::text[],'붉은 양배추 용액이 산성·염기성 용액에서 띠는 색깔 계열을 거꾸로 안다','산성 붉은색 계열 · 염기성 푸른색이나 노란색 계열'),
('SC6-1-u1-X14','sci',6,'u1',ARRAY['SC6-1-u1-C8']::text[],'지시약의 색은 하나로 딱 정해져 있다고 여겨 비슷한 계열의 색으로 관찰해야 함(농도에 따른 차이)을 놓친다','특정 색보다 비슷한 계열'),
('SC6-1-u1-X15','sci',6,'u1',ARRAY['SC6-1-u1-C9']::text[],'여섯 용액을 산성 용액과 염기성 용액으로 잘못 가른다(석회수를 산성으로, 레몬즙을 염기성으로 등)','식초·레몬즙·묽은 염산이 한 무리'),
('SC6-1-u1-X16','sci',6,'u1',ARRAY['SC6-1-u1-C9']::text[],'지시약이 다르면 산성·염기성으로 분류한 결과도 달라진다고 여긴다','색깔은 달라도 분류 결과는 같아요'),
('SC6-1-u1-X17','sci',6,'u1',ARRAY['SC6-1-u1-C10']::text[],'산성 용액이 삶은 달걀흰자·삶은 닭 가슴살을 녹인다고 여기거나, 달걀 껍데기·조개껍데기가 산성 용액에서 변하지 않는다고 여긴다','산성 용액은 껍데기를 녹여요'),
('SC6-1-u1-X18','sci',6,'u1',ARRAY['SC6-1-u1-C11']::text[],'염기성 용액이 달걀 껍데기·조개껍데기를 녹인다고 여기거나, 삶은 달걀흰자·삶은 닭 가슴살이 염기성 용액에서 변하지 않는다고 여긴다','염기성 용액은 흰자·닭 가슴살을 녹여요'),
('SC6-1-u1-X19','sci',6,'u1',ARRAY['SC6-1-u1-C11']::text[],'염기성 용액과 단백질의 반응이 곧바로 나타난다고 여기거나, 넣자마자 변화가 없다고 성급히 결론 짓는다','시간이 지나면서 나타나요'),
('SC6-1-u1-X20','sci',6,'u1',ARRAY['SC6-1-u1-C10','SC6-1-u1-C11']::text[],'주요 성분(탄산 칼슘·단백질)과 반응하는 용액을 바꾸어 짝짓거나, 두 용액이 같은 물질을 녹인다고 여긴다','탄산 칼슘 ↔ 산성 · 단백질 ↔ 염기성'),
('SC6-1-u1-X21','sci',6,'u1',ARRAY['SC6-1-u1-C12']::text[],'두 용액의 성질을 견주는 실험에서 같게 할 조건(같은 물질·같은 크기·같은 관찰 시간)을 놓친다','용액만 다르게'),
('SC6-1-u1-X22','sci',6,'u1',ARRAY['SC6-1-u1-C13']::text[],'두 용액을 섞을 때 붉은 양배추 용액의 색깔이 변하는 방향을 거꾸로 안다','염기성을 넣을수록 노란색 계열 쪽으로'),
('SC6-1-u1-X23','sci',6,'u1',ARRAY['SC6-1-u1-C13','SC6-1-u1-C14']::text[],'산성 용액과 염기성 용액을 섞어도 성질이 변하지 않는다고, 또는 두 성질이 모두 더 강해진다고 여긴다','처음 성질이 약해져요'),
('SC6-1-u1-X24','sci',6,'u1',ARRAY['SC6-1-u1-C14']::text[],'두 용액을 섞으면 곧바로 물이 되거나 용액이 사라진다고 여긴다','색으로 성질 변화를 봐요'),
('SC6-1-u1-X25','sci',6,'u1',ARRAY['SC6-1-u1-C14']::text[],'넣는 양과 관계없이 결과가 같다고 여겨, 많이 넣을수록 성질이 차례로 변하고 더 많이 넣은 용액의 성질을 나타냄을 놓친다','넣을수록 차례로 변해요'),
('SC6-1-u1-X26','sci',6,'u1',ARRAY['SC6-1-u1-C15']::text[],'섞을 때의 성질 변화를 이용하는 예를 잘못 안다(산성이 강한 흙이나 염산이 샌 곳에 산성 물질을 더 뿌린다 등)','염기성인 석회 가루'),
('SC6-1-u1-X27','sci',6,'u1',ARRAY['SC6-1-u1-C16','SC6-1-u1-C17']::text[],'생활에서 이용하는 용액의 성질(산성·염기성)을 바꾸어 가른다','식초·레몬즙·변기 세제·구연산은 산성'),
('SC6-1-u1-X28','sci',6,'u1',ARRAY['SC6-1-u1-C18']::text[],'없애려는 물질과 같은 성질의 용액을 써야 한다고 여기거나, 반대 성질의 용액을 이용하는 까닭을 잇지 못한다','반대 성질과 만나면 약해져요'),
('SC6-1-u1-X29','sci',6,'u1',ARRAY['SC6-1-u1-C16','SC6-1-u1-C17']::text[],'산성 용액과 염기성 용액은 위험해서 실험실에서만 쓰고 생활에는 이용하지 않는다고 여긴다','요리·청소·약에도 써요'),
('SC6-1-u1-X30','sci',6,'u1',ARRAY['SC6-1-u1-C19']::text[],'산성화의 뜻을 잘못 안다(온도가 높아지는 것, 색깔이 진해지는 것, 공기 중으로 날아가는 것 등으로)','점차 산성으로 변하는 것'),
('SC6-1-u1-X31','sci',6,'u1',ARRAY['SC6-1-u1-C19']::text[],'산성비·해양 산성화·토양 산성화의 뜻이나 주된 원인을 서로 바꾸어 안다','비 · 바닷물 · 흙'),
('SC6-1-u1-X32','sci',6,'u1',ARRAY['SC6-1-u1-C20']::text[],'피해 사례를 다른 산성화의 피해로 바꾸어 가르거나, 산성화가 생물에게 이롭다고 여긴다','조개껍데기는 바다, 식물 생장은 흙'),
('SC6-1-u1-X33','sci',6,'u1',ARRAY['SC6-1-u1-C20']::text[],'산성화는 생물에게만 피해를 주고 건물·조각상·문화재에는 영향이 없다고 여긴다','대리암 조각상도 훼손돼요'),
('SC6-1-u1-X34','sci',6,'u1',ARRAY['SC6-1-u1-C20']::text[],'산호초 백화 현상의 원인을 해양 산성화 하나로만 단정한다','수온·염분·유해 물질도 원인'),
('SC6-1-u1-X35','sci',6,'u1',ARRAY['SC6-1-u1-C21','SC6-1-u1-C22']::text[],'산성화는 우리와 관계없는 먼 곳의 일이라 알리거나 줄일 필요가 없다고 여긴다','전 세계적인 환경 문제'),
('SC6-1-u1-X36','sci',6,'u1',ARRAY['SC6-1-u1-C21']::text[],'산성화는 사람의 활동과 관계없이 저절로 생기고, 시간이 지나면 저절로 사라진다고 여긴다','사람의 활동이 원인'),
('SC6-1-u1-X37','sci',6,'u1',ARRAY['SC6-1-u1-C21']::text[],'산성화의 원인과 대책을 바꾸어 가르거나, 오염 물질을 늘리는 행동을 대책으로 여긴다','친환경 에너지 · 대중교통'),
('SC6-1-u1-X38','sci',6,'u1',ARRAY['SC6-1-u1-C22']::text[],'알림 동영상을 만드는 순서나 조사할 내용을 잘못 안다(조사 없이 만들기, 공유부터 하기 등)','조사 → 계획 → 만들기 → 공유'),
('SC6-1-u1-X39','sci',6,'u1',ARRAY['SC6-1-u1-C22']::text[],'자료를 만들고 나누는 태도를 잘못 안다(출처 없이 가져다 쓰기, 꾸밈만 중시하기, 비난하는 댓글, 혼자 다 하기 등)','출처 · 협력 · 잘한 점 댓글'),
('SC6-1-u1-X40','sci',6,'u1',ARRAY['SC6-1-u1-C23']::text[],'환경 과학자가 하는 일이나 토양·대기·수질 분야가 맡는 일을 잘못 안다','흙 · 공기 · 물을 조사·분석'),
('SC6-1-u1-X41','sci',6,'u1',ARRAY['SC6-1-u1-C20','SC6-1-u1-C10']::text[],'조개껍데기·산호·대리암이 산성에 피해를 입는 까닭(주요 성분인 탄산 칼슘이 산성 용액에 녹음)을 산성화 피해와 잇지 못한다','탄산 칼슘은 산성 용액에 녹아요')
